 1→function withOpacity(variableName) {
 2→  return ({ opacityValue }) => {
 3→    if (opacityValue !== undefined) {
 4→      return `rgba(var(${variableName}), ${opacityValue})`;
 5→    }
 6→    return `rgb(var(${variableName}))`;
 7→  };
 8→}
