 1→export const prerender = false;
 2→import { supabase } from "lib/supabase";
 3→
 4→export async function GET({ params }: { params: { name: string } }) {
 5→  const id = params.name;
 6→  console.log(id);
 7→  await supabase.rpc("increment", { x: 1, name: id });
 8→  const views = await supabase
 9→    .from("blog_views")
10→    .select("view")
11→    .eq("blog_name", id);
12→  const view = views.data![0].view ?? 0;
13→
14→  return new Response(JSON.stringify(view), {
15→    status: 200,
16→    headers: {
17→      "Content-Type": "application/json",
18→    },
19→  });
20→}
