  1→import Fuse from "fuse.js";
  2→import { useEffect, useRef, useState, useMemo } from "react";
  3→import Card from "@components/Card";
  4→import slugify from "@utils/slugify";
  5→import type { CollectionEntry } from "astro:content";
  6→
  7→export type SearchItem = {
  8→  title: string;
  9→  description: string;
 10→  data: CollectionEntry<"blog">["data"];
 11→};
 12→
 13→interface Props {
 14→  searchList: SearchItem[];
 15→}
 16→
 17→interface SearchResult {
 18→  item: SearchItem;
 19→  refIndex: number;
 20→}
 21→
 22→export default function SearchBar({ searchList }: Props) {
 23→  const inputRef = useRef<HTMLInputElement>(null);
 24→  const [inputVal, setInputVal] = useState("");
 25→  const [searchResults, setSearchResults] = useState<SearchResult[] | null>(
 26→    null
 27→  );
 28→
 29→  const handleChange = (e: React.FormEvent<HTMLInputElement>) => {
 30→    setInputVal(e.currentTarget.value);
 31→  };
 32→
 33→  const fuse = useMemo(
 34→    () =>
 35→      new Fuse(searchList, {
 36→        keys: ["title", "description"],
 37→        includeMatches: true,
 38→        minMatchCharLength: 2,
 39→        threshold: 0.5,
 40→      }),
 41→    [searchList]
 42→  );
 43→
 44→  useEffect(() => {
 45→    // if URL has search query,
 46→    // insert that search query in input field
 47→    const searchUrl = new URLSearchParams(window.location.search);
 48→    const searchStr = searchUrl.get("q");
 49→    if (searchStr) setInputVal(searchStr);
 50→
 51→    // put focus cursor at the end of the string
 52→    setTimeout(function () {
 53→      inputRef.current!.selectionStart = inputRef.current!.selectionEnd =
 54→        searchStr?.length || 0;
 55→    }, 50);
 56→  }, []);
 57→
 58→  useEffect(() => {
 59→    // Add search result only if
 60→    // input value is more than one character
 61→    let inputResult = inputVal.length > 1 ? fuse.search(inputVal) : [];
 62→    setSearchResults(inputResult);
 63→
 64→    // Update search string in URL
 65→    if (inputVal.length > 0) {
 66→      const searchParams = new URLSearchParams(window.location.search);
 67→      searchParams.set("q", inputVal);
 68→      const newRelativePathQuery =
 69→        window.location.pathname + "?" + searchParams.toString();
 70→      history.replaceState(history.state, "", newRelativePathQuery);
 71→    } else {
 72→      history.replaceState(history.state, "", window.location.pathname);
 73→    }
 74→  }, [inputVal]);
 75→
 76→  return (
 77→    <>
 78→      <label className="relative block">
 79→        <span className="absolute inset-y-0 left-0 flex items-center pl-2 opacity-75">
 80→          <svg xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
 81→            <path d="M19.023 16.977a35.13 35.13 0 0 1-1.367-1.384c-.372-.378-.596-.653-.596-.653l-2.8-1.337A6.962 6.962 0 0 0 16 9c0-3.859-3.14-7-7-7S2 5.141 2 9s3.14 7 7 7c1.763 0 3.37-.66 4.603-1.739l1.337 2.8s.275.224.653.596c.387.363.896.854 1.384 1.367l1.358 1.392.604.646 2.121-2.121-.646-.604c-.379-.372-.885-.866-1.391-1.36zM9 14c-2.757 0-5-2.243-5-5s2.243-5 5-5 5 2.243 5 5-2.243 5-5 5z"></path>
 82→          </svg>
 83→        </span>
 84→        <input
 85→          className="block w-full rounded border border-skin-fill 
 86→        border-opacity-40 bg-skin-fill py-3 pl-10
 87→        pr-3 placeholder:italic placeholder:text-opacity-75 
 88→        focus:border-skin-accent focus:outline-none"
 89→          placeholder="Search for anything..."
 90→          type="text"
 91→          name="search"
 92→          value={inputVal}
 93→          onChange={handleChange}
 94→          autoComplete="off"
 95→          autoFocus
 96→          ref={inputRef}
 97→        />
 98→      </label>
 99→
100→      {inputVal.length > 1 && (
101→        <div className="mt-8">
102→          Found {searchResults?.length}
103→          {searchResults?.length && searchResults?.length === 1
104→            ? " result"
105→            : " results"}{" "}
106→          for '{inputVal}'
107→        </div>
108→      )}
109→
110→      <ul>
111→        {searchResults &&
112→          searchResults.map(({ item, refIndex }) => (
113→            <Card
114→              href={`/posts/${slugify(item.data)}`}
115→              frontmatter={item.data}
116→              key={`${refIndex}-${slugify(item.data)}`}
117→            />
118→          ))}
119→      </ul>
120→    </>
121→  );
122→}
