 3→
 4→const blog = defineCollection({
 5→  type: "content",
 6→  schema: ({ image }) =>
 7→    z.object({
 8→      author: z.string().default(SITE.author),
 9→      pubDatetime: z.coerce.date(),
10→      title: z.string(),
11→      postSlug: z.string().optional(),
12→      featured: z.boolean().optional(),
13→      draft: z.boolean().optional(),
14→      tags: z.array(z.string()).default(["others"]),
15→      ogImage: image()
16→        .refine(img => img.width >= 1200 && img.height >= 630, {
17→          message: "OpenGraph image must be at least 1200 X 630 pixels!",
18→        })
19→        .or(z.string())
20→        .optional(),
21→      description: z.string(),
22→      canonicalURL: z.string().optional(),
23→    }),
24→});
25→
26→const randomThought = defineCollection({
27→  schema: z.object({
28→    date: z.coerce.date(),
29→  }),
30→});
31→
32→export const collections = { blog, "random-thoughts": randomThought };
