22→const { pageNum, totalPages, posts } = Astro.props;
23→
24→const prev = pageNum > 1 ? "" : "disabled";
25→const next = pageNum < totalPages ? "" : "disabled";
26→
27→const views = await supabase.from("blog_views").select("*");
28→
