 2→import { type CollectionEntry, getCollection } from "astro:content";
 3→import Posts from "@layouts/Posts.astro";
 4→import PostDetails from "@layouts/PostDetails.astro";
 5→import getSortedPosts from "@utils/getSortedPosts";
 6→import getPageNumbers from "@utils/getPageNumbers";
 7→import slugify from "@utils/slugify";
 8→import { SITE } from "@config";
 9→
10→export interface Props {
11→  post: CollectionEntry<"blog">;
12→}
13→
14→export async function getStaticPaths() {
15→  const posts = await getCollection("blog", ({ data }) => !data.draft);
16→
17→  const postResult = posts.map(post => ({
18→    params: { slug: slugify(post.data) },
19→    props: { post },
20→  }));
21→
22→  const pagePaths = getPageNumbers(posts.length).map(pageNum => ({
23→    params: { slug: String(pageNum) },
24→  }));
25→
26→  return [...postResult, ...pagePaths];
27→}
28→
29→const { slug } = Astro.params;
30→const { post } = Astro.props;
31→
32→const posts = await getCollection("blog");
33→
34→const sortedPosts = getSortedPosts(posts);
35→
36→const totalPages = getPageNumbers(sortedPosts.length);
37→
38→const currentPage =
39→  slug && !isNaN(Number(slug)) && totalPages.includes(Number(slug))
40→    ? Number(slug)
41→    : 0;
42→const lastPost = currentPage * SITE.postPerPage;
43→const startPost = lastPost - SITE.postPerPage;
44→
45→const paginatedPosts = sortedPosts.slice(startPost, lastPost);
46→---
47→
48→{
49→  post ? (
50→    <PostDetails post={post} />
51→  ) : (
52→    <Posts
53→      posts={paginatedPosts}
54→      pageNum={currentPage}
55→      totalPages={totalPages.length}
56→    />
57→  )
58→}
