    @apply inline-block h-6 w-6 fill-skin-base group-hover:fill-skin-accent;
  }
  svg.icon-tabler {
    @apply inline-block h-6 w-6 scale-125 fill-transparent 
    stroke-current stroke-2 opacity-90 group-hover:fill-transparent 
    sm:scale-110;
  }
  .prose {
    @apply /* */ 
    prose-headings:!mb-3 prose-headings:!text-skin-base prose-h3:italic 
    prose-h3:!text-skin-accent prose-p:!text-skin-base prose-a:!text-skin-base
    prose-a:!decoration-dashed prose-a:underline-offset-8
    hover:prose-a:text-skin-accent prose-blockquote:!border-l-skin-accent
    prose-blockquote:border-opacity-100 prose-blockquote:opacity-80
    prose-figcaption:!text-skin-base


    prose-figcaption:opacity-70 prose-strong:!text-skin-base 
    prose-code:rounded prose-code:bg-skin-card prose-code:bg-opacity-75 
    prose-code:p-1 prose-code:!text-skin-base
    prose-code:before:!content-[''] prose-code:after:!content-[''] 
    prose-pre:!text-skin-base prose-ol:!text-skin-base prose-ul:overflow-x-clip
     prose-ul:!text-skin-base prose-li:marker:!text-skin-accent
    prose-table:text-skin-base prose-th:border
    prose-th:border-skin-line prose-td:border 
    prose-td:border-skin-line prose-img:mx-auto 
    prose-img:!mt-2 prose-img:border-2 
    prose-img:border-skin-line prose-hr:!border-skin-line;
  }

  /* custom styles */

  /* imag enlarge on hover also hide overflow when enlargening on mobile
     changes to disable it on mobile 
  */
  .prose {
    @apply prose-img:relative prose-img:z-50 prose-img:transition-transform;
  }

  @media (min-width: 768px) {
    .prose > img:hover {
      transform: scale(1.5);
      z-index: 60;
    }
  }
  .prose img {
    border-width: 0 !important;
  }

  /* apply style to parent if parent has child */
  /* i'm not sure why applying to body works, but applying to html, and .main-content didn't */
  /* maybe something iffy with html element but prolly cause .main-content width isn't defined strongly? */
  body {
    /* okay seems like overflow hidden lags the website??? */
    /* overflow-x: hidden; */
  }
  /* .main-content {
    overflow-x:hidden;
  } */

  /* remove quotes from blockquote */
  .prose > blockquote > p::before {
    content: "" !important;
  }
  .prose > blockquote > p::after {
    content: "" !important;
  }

  /* end custom styles */
  .prose a {
    @apply break-words hover:!text-skin-accent;
  }
  .prose thead th:first-child,
  tbody td:first-child,
  tfoot td:first-child {
    padding-left: 0.5714286em;
  }
  .prose h2#table-of-contents {
    @apply mb-2;
  }
  .prose details {
    @apply inline-block cursor-pointer select-none text-skin-base;
  }
  .prose summary {
    @apply focus-outline;
  }
  .prose h2#table-of-contents + p {
    @apply hidden;
  }

  /* ===== scrollbar ===== */
  html {
    /* overflow-y: scroll; */
  }

  /* width */
  ::-webkit-scrollbar {
    @apply w-3;
  }

  /* Track */
  ::-webkit-scrollbar-track {
    @apply bg-skin-fill;
  }

  /* Handle */
  ::-webkit-scrollbar-thumb {
    @apply bg-skin-card;
  }

  /* Handle on hover */
  ::-webkit-scrollbar-thumb:hover {
    @apply bg-skin-card-muted;
  }

  code,
  blockquote {
    word-wrap: break-word;
  }

  pre > code {
    white-space: pre;
  }
}

@layer components {
  .display-none {
    @apply hidden;
  }
  .focus-outline {
    @apply outline-2 outline-offset-1 outline-skin-fill focus-visible:no-underline focus-visible:outline-dashed;
  }
}

