@import "tailwindcss";
@import url("https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@300;400;500;600;700&display=swap");

@plugin "@tailwindcss/typography";

@theme {
  --font-mono: "Space Grotesk", monospace;

  --color-primary: #48bb78;
  --color-secondary: #5f6c80;
  --color-toggle-icon: #2d3748;
  --color-heading: #000;
  --color-divide: #cbd5e0;
  --color-muted: #edf2f7;

  --color-skin-fill: rgb(var(--color-fill));
  --color-skin-accent: rgb(var(--color-accent));
  --color-skin-inverted: rgb(var(--color-fill));
  --color-skin-card: rgb(var(--color-card));
  --color-skin-card-muted: rgb(var(--color-card-muted));

  --color-skin-text-base: rgb(var(--color-text-base));
  --color-skin-text-accent: rgb(var(--color-accent));
  --color-skin-text-inverted: rgb(var(--color-fill));

  --color-skin-border-line: rgb(var(--color-border));
  --color-skin-border-fill: rgb(var(--color-text-base));
  --color-skin-border-accent: rgb(var(--color-accent));

  --color-skin-outline-fill: rgb(var(--color-accent));

  --color-skin-fill-base: rgb(var(--color-text-base));
  --color-skin-fill-accent: rgb(var(--color-accent));
}

@layer base {
  :root,
  html[data-theme="light"] {
    --color-fill: 251, 254, 251;
    --color-text-base: 40, 39, 40;
    --color-accent: 72, 187, 120;
    --color-card: 230, 230, 230;
    --color-card-muted: 205, 205, 205;
    --color-border: 236, 233, 233;
  }

  body {
    @apply flex min-h-[100svh] flex-col bg-skin-fill font-mono text-skin-text-base
    selection:bg-skin-accent/70 selection:text-skin-text-inverted;
  }
  section,
  footer {
    @apply mx-auto max-w-3xl px-4;
  }
  a {
    @apply outline-2 outline-offset-1 outline-skin-outline-fill
    focus-visible:no-underline focus-visible:outline-dashed;
  }
  svg {
    @apply inline-block h-6 w-6 fill-skin-fill-base group-hover:fill-skin-fill-accent;
  }
  svg.icon-tabler {
    @apply inline-block h-6 w-6 scale-125 fill-transparent
    stroke-current stroke-2 opacity-90 group-hover:fill-transparent
    sm:scale-110;
  }
  .prose {
    @apply
    prose-headings:mb-3! prose-headings:text-skin-text-base! prose-h3:italic
    prose-h3:text-skin-text-accent! prose-p:text-skin-text-base! prose-a:text-skin-text-base!
    prose-a:decoration-dashed! prose-a:underline-offset-8
    hover:prose-a:text-skin-text-accent prose-blockquote:border-l-skin-border-accent!
    prose-blockquote:border-opacity-100 prose-blockquote:opacity-80
    prose-figcaption:text-skin-text-base!

    prose-figcaption:opacity-70 prose-strong:text-skin-text-base!
    prose-code:rounded prose-code:bg-skin-card prose-code:bg-opacity-75
    prose-code:p-1 prose-code:text-skin-text-base!
    prose-code:before:content-['']! prose-code:after:content-['']!
    prose-pre:text-skin-text-base! prose-ol:text-skin-text-base! prose-ul:overflow-x-clip
     prose-ul:text-skin-text-base! prose-li:marker:text-skin-text-accent!
    prose-table:text-skin-text-base prose-th:border
    prose-th:border-skin-border-line prose-td:border
    prose-td:border-skin-border-line prose-img:mx-auto
    prose-img:mt-2! prose-img:border-2
    prose-img:border-skin-border-line prose-hr:border-skin-border-line!;
  }

  /* image enlarge on hover, disabled on mobile */
  .prose {
    @apply prose-img:relative prose-img:z-50 prose-img:transition-transform;
  }

  @media (min-width: 768px) {
    .prose > img:hover {
      transform: scale(1.5);
      z-index: 60;
    }
  }
  .prose img {
    border-width: 0 !important;
  }

  /* remove quotes from blockquote */
  .prose > blockquote > p::before {
    content: "" !important;
  }
  .prose > blockquote > p::after {
    content: "" !important;
  }

  .prose a {
    @apply break-words hover:text-skin-text-accent!;
  }
  .prose thead th:first-child,
  tbody td:first-child,
  tfoot td:first-child {
    padding-left: 0.5714286em;
  }
  .prose h2#table-of-contents {
    @apply mb-2;
  }
  .prose details {
    @apply inline-block cursor-pointer select-none text-skin-text-base;
  }
  .prose summary {
    @apply focus-outline;
  }
  .prose h2#table-of-contents + p {
    @apply hidden;
  }

  /* ===== scrollbar ===== */
  ::-webkit-scrollbar {
    @apply w-3;
  }
  ::-webkit-scrollbar-track {
    @apply bg-skin-fill;
  }
  ::-webkit-scrollbar-thumb {
    @apply bg-skin-card;
  }
  ::-webkit-scrollbar-thumb:hover {
    @apply bg-skin-card-muted;
  }

  code,
  blockquote {
    word-wrap: break-word;
  }

  pre > code {
    white-space: pre;
  }
}

@utility display-none {
  @apply hidden;
}

@utility focus-outline {
  @apply outline-2 outline-offset-1 outline-skin-outline-fill focus-visible:no-underline focus-visible:outline-dashed;
}

